<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-dark-font-style:italic;--shiki-light:#c13617;--shiki-light-font-style:inherit;">               max_iterations</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">=</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">100</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-dark-font-style:italic;--shiki-light:#c13617;--shiki-light-font-style:inherit;"> max_nodes</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">=</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">100_000</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span></span>
